import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';
import persianDate from './persianDate';

export const announcementGenerator = {
  // Generate poster HTML
  generatePosterHTML(announcement) {
    const {
      title,
      description,
      date,
      time,
      venue,
      price,
      program_title,
      program_type,
      actors
    } = announcement;

    const persianDateStr = persianDate.toPersian(date);
    const dayName = persianDate.getDayName(date);

    return `
      <div dir="rtl" style="
        width: 800px;
        height: 1000px;
        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        padding: 40px;
        font-family: 'IRANSans', Tahoma, Arial, sans-serif;
        color: white;
        position: relative;
        overflow: hidden;
      ">
        <!-- Decorative background -->
        <div style="
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="20" cy="20" r="2" fill="rgba(255,255,255,0.1)"/><circle cx="80" cy="40" r="1.5" fill="rgba(255,255,255,0.1)"/><circle cx="40" cy="80" r="1" fill="rgba(255,255,255,0.1)"/></svg>');
          z-index: 1;
        "></div>

        <!-- Main content -->
        <div style="position: relative; z-index: 2; height: 100%;">
          <!-- Header -->
          <div style="
            text-align: center;
            margin-bottom: 40px;
            border-bottom: 2px solid rgba(255,255,255,0.3);
            padding-bottom: 20px;
          ">
            <h1 style="
              font-size: 48px;
              margin: 0 0 10px 0;
              font-weight: bold;
              text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
            ">${title}</h1>
            ${program_title ? `<h2 style="
              font-size: 32px;
              margin: 0;
              font-weight: normal;
              color: rgba(255,255,255,0.9);
            ">${program_title}</h2>` : ''}
          </div>

          <!-- Date and Time Section -->
          <div style="
            background: rgba(255,255,255,0.1);
            border-radius: 15px;
            padding: 25px;
            margin-bottom: 30px;
            backdrop-filter: blur(10px);
          ">
            <div style="display: flex; justify-content: space-between; align-items: center;">
              <div style="text-align: center;">
                <div style="font-size: 24px; font-weight: bold; margin-bottom: 5px;">${dayName}</div>
                <div style="font-size: 28px;">${persianDateStr}</div>
              </div>
              <div style="text-align: center;">
                <div style="font-size: 20px; margin-bottom: 5px;">ساعت</div>
                <div style="font-size: 32px; font-weight: bold;">${time}</div>
              </div>
            </div>
          </div>

          <!-- Venue Section -->
          <div style="
            background: rgba(255,255,255,0.1);
            border-radius: 15px;
            padding: 25px;
            margin-bottom: 30px;
            backdrop-filter: blur(10px);
          ">
            <div style="font-size: 20px; margin-bottom: 10px;">📍 محل برگزاری</div>
            <div style="font-size: 24px; font-weight: bold;">${venue}</div>
          </div>

          <!-- Description -->
          <div style="
            background: rgba(255,255,255,0.1);
            border-radius: 15px;
            padding: 25px;
            margin-bottom: 30px;
            backdrop-filter: blur(10px);
            min-height: 150px;
          ">
            <div style="font-size: 20px; margin-bottom: 15px;">📝 توضیحات</div>
            <div style="font-size: 18px; line-height: 1.6;">${description}</div>
          </div>

          <!-- Actors Section -->
          ${actors && actors.length > 0 ? `
          <div style="
            background: rgba(255,255,255,0.1);
            border-radius: 15px;
            padding: 25px;
            margin-bottom: 30px;
            backdrop-filter: blur(10px);
          ">
            <div style="font-size: 20px; margin-bottom: 15px;">🎭 عوامل</div>
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
              ${actors.map(actor => `
                <div style="font-size: 16px;">
                  <strong>${actor.name}</strong>
                  ${actor.role_in_program ? `<br><small>${actor.role_in_program}</small>` : ''}
                </div>
              `).join('')}
            </div>
          </div>
          ` : ''}

          <!-- Price Section -->
          ${price ? `
          <div style="
            background: rgba(255,255,255,0.1);
            border-radius: 15px;
            padding: 25px;
            backdrop-filter: blur(10px);
            text-align: center;
          ">
            <div style="font-size: 20px; margin-bottom: 10px;">💰 قیمت بلیت</div>
            <div style="font-size: 32px; font-weight: bold; color: #FFD700;">${price}</div>
          </div>
          ` : ''}

          <!-- Footer -->
          <div style="
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            text-align: center;
            padding: 20px;
            border-top: 2px solid rgba(255,255,255,0.3);
          ">
            <div style="font-size: 16px; opacity: 0.8;">
              تهیه شده با سامانه رسا
            </div>
            <div style="font-size: 14px; opacity: 0.6; margin-top: 5px;">
              ${persianDate.getCurrentDateTime()}
            </div>
          </div>
        </div>
      </div>
    `;
  },

  // Generate poster image
  async generatePosterImage(announcement) {
    const html = this.generatePosterHTML(announcement);

    // Create temporary container
    const container = document.createElement('div');
    container.innerHTML = html;
    container.style.position = 'absolute';
    container.style.left = '-9999px';
    container.style.top = '-9999px';
    document.body.appendChild(container);

    try {
      const canvas = await html2canvas(container, {
        width: 800,
        height: 1000,
        scale: 2,
        backgroundColor: null,
        useCORS: true,
        allowTaint: true
      });

      document.body.removeChild(container);
      return canvas.toDataURL('image/png', 1.0);
    } catch (error) {
      document.body.removeChild(container);
      throw error;
    }
  },

  // Generate PDF
  async generatePDF(announcement) {
    const imageData = await this.generatePosterImage(announcement);

    const pdf = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4'
    });

    // Calculate dimensions to fit A4
    const pdfWidth = 210; // A4 width in mm
    const pdfHeight = 297; // A4 height in mm
    const imageWidth = 800;
    const imageHeight = 1000;

    // Calculate scaling to fit the page
    const scale = Math.min(pdfWidth / imageWidth, pdfHeight / imageHeight) * 25.4; // Convert pixels to mm
    const width = imageWidth * scale / 25.4;
    const height = imageHeight * scale / 25.4;

    // Center the image
    const x = (pdfWidth - width) / 2;
    const y = (pdfHeight - height) / 2;

    pdf.addImage(imageData, 'PNG', x, y, width, height);

    return pdf.output('blob');
  }
};

export default announcementGenerator;
